using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace Overclock {
 static class ScrollTests {
  static void Check(bool value,string text){if(!value)throw new Exception("Scrolling: "+text);}
  static void Call(Control control,string name,EventArgs args){try{control.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(control,new object[]{args});}catch(TargetInvocationException e){throw new Exception(name+": "+e.InnerException);}}
  public static string Run(string folder){
   using(var form=new Form{Text="ISOLATED SCROLL FIXTURE — NOT LIVE TELEMETRY",Size=new Size(1280,720),BackColor=Theme.Background,StartPosition=FormStartPosition.CenterScreen}){
    var columns=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1};for(int i=0;i<3;i++)columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/3));columns.RowStyles.Add(new RowStyle(SizeType.Percent,100));var grid=Theme.Grid("Fixture sensor","Current","Minimum","Maximum","Unit");grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;foreach(DataGridViewColumn c in grid.Columns)c.Width=c.Index==0?320:150;for(int i=0;i<1200;i++)grid.Rows.Add("Isolated test row "+i,i,0,i,"fixture");var tree=new DarkTree{Dock=DockStyle.Fill,BackColor=Theme.Surface,ForeColor=Theme.Text,ItemHeight=28,Font=Theme.Face(11)};for(int i=0;i<12;i++){var root=tree.Nodes.Add("Isolated hardware branch "+i+" — long identity for horizontal overflow");for(int j=0;j<30;j++)root.Nodes.Add("Fixture reading "+i+" / "+j);}tree.ExpandAll();var log=new DarkRichTextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,WordWrap=false,BackColor=Theme.Surface,ForeColor=Theme.Text,Font=new Font("Consolas",11),BorderStyle=BorderStyle.None,Text=string.Join("\r\n",Enumerable.Range(0,5000).Select(i=>"FIXTURE ONLY "+i+" — "+new string('x',110)).ToArray())};columns.Controls.Add(tree);columns.Controls.Add(grid);columns.Controls.Add(log);form.Controls.Add(columns);DarkScrolling.Install(form);form.Show();Application.DoEvents();var frames=columns.Controls.OfType<DarkScrollFrame>().ToArray();foreach(var f in frames)f.RefreshRange();var gf=frames.Single(f=>f.Host==grid);var tf=frames.Single(f=>f.Host==tree);var lf=frames.Single(f=>f.Host==log);
    Check(gf.Vertical.Maximum>1000&&gf.Horizontal.Maximum>0,"grid extents/axes");gf.Vertical.Value=gf.Vertical.Maximum;Check(grid.FirstDisplayedScrollingRowIndex>1000,"grid end drag mapping");gf.Horizontal.Value=gf.Horizontal.Maximum;Check(grid.HorizontalScrollingOffset>0,"grid horizontal mapping");grid.Rows[1100].Selected=true;var selected=grid.Rows[1100];grid.Rows[1100].Cells[1].Value=123;gf.RefreshRange();Check(selected.Selected,"selection changed after live cell update");
    Call(gf.Vertical,"OnKeyDown",new KeyEventArgs(Keys.Home));Check(gf.Vertical.Value==0&&grid.FirstDisplayedScrollingRowIndex==0,"keyboard Home");Call(gf.Vertical,"OnKeyDown",new KeyEventArgs(Keys.PageDown));Check(gf.Vertical.Value>0,"keyboard page step");gf.Vertical.Value=0;gf.Vertical.Wheel(-60);Check(gf.Vertical.Value==0,"partial wheel delta");gf.Vertical.Wheel(-60);Check(gf.Vertical.Value==3,"wheel delta accumulation");var thumb=gf.Vertical.Thumb;Call(gf.Vertical,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,thumb.X+2,thumb.Y+3,0));Call(gf.Vertical,"OnMouseMove",new MouseEventArgs(MouseButtons.Left,0,thumb.X+2,gf.Vertical.Height-2,0));Call(gf.Vertical,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,thumb.X+2,gf.Vertical.Height-2,0));Check(gf.Vertical.Value>=gf.Vertical.Maximum-1,"thumb drag to end");int before=gf.Vertical.Value;Call(gf.Vertical,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,3,3,0));Check(gf.Vertical.Value<before,"track paging");
    Check(tf.Vertical.Maximum>278&&tf.Horizontal.Maximum>0,"tree extents");tf.Vertical.Value=tf.Vertical.Maximum;Check(tree.Top<0&&-tree.Top==tf.Vertical.Value*tree.ItemHeight,"tree clipped viewport scroll");tf.Horizontal.Value=tf.Horizontal.Maximum;Check(tree.Left<0,"tree horizontal viewport");tree.CollapseAll();tf.RefreshRange();Check(tf.Vertical.Value<=tf.Vertical.Maximum,"tree collapse clamping");tree.ExpandAll();tf.RefreshRange();typeof(Control).GetMethod("RecreateHandle",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tree,null);tf.RefreshRange();Check(tf.Vertical.Maximum>278,"tree handle recreation");
    Check(lf.Vertical.Maximum>4000&&lf.Horizontal.Maximum>0,"log extents");lf.Vertical.Value=4000;int line=(int)ScrollNative.SendMessage(log.Handle,ScrollNative.GetFirstLine,IntPtr.Zero,IntPtr.Zero);Check(line>3900,"log vertical mapping");lf.Horizontal.Value=lf.Horizontal.Maximum;Check(ScrollNative.RichPosition(log.Handle).X>0,"rich log horizontal mapping");log.Select(20,10);lf.Vertical.Value=4000;log.Text+="\r\nFIXTURE appended";lf.RefreshRange();Check(log.SelectionStart==20&&log.SelectionLength==10,"log text selection persistence");Check((int)ScrollNative.SendMessage(log.Handle,ScrollNative.GetFirstLine,IntPtr.Zero,IntPtr.Zero)>3900,"log viewport persistence");
    using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(folder,"scrolling-100dpi-fixture.png"));}gf.Vertical.Value=0;gf.Horizontal.Value=0;tree.Nodes.Clear();tf.RefreshRange();Check(tf.Vertical.Maximum==0,"empty tree extent");Check(gf.Vertical.AccessibilityObject.Role==AccessibleRole.ScrollBar&&gf.Vertical.AccessibilityObject.Value!=null,"accessible scrollbar role/value");var combo=new DarkCombo{Dock=DockStyle.Top,DropDownWidth=400,AccessibleName="Isolated choice fixture"};for(int i=0;i<40;i++)combo.Items.Add("Fixture choice "+i);Theme.Combo(combo);form.Controls.Add(combo);combo.SelectedIndex=0;combo.OpenPopup();Application.DoEvents();Check(combo.Popup!=null,"custom popup did not open");DarkScrolling.Audit(form);DarkScrolling.Audit(combo.Popup);var popupFrame=combo.Popup.Items.OfType<ToolStripControlHost>().Select(v=>v.Control).OfType<DarkScrollFrame>().Single();popupFrame.RefreshRange();popupFrame.Vertical.Value=popupFrame.Vertical.Maximum;var popupList=(ListBox)popupFrame.Host;Check(popupList.TopIndex>20,"popup list overflow");using(var image=new Bitmap(combo.Popup.Width,combo.Popup.Height)){combo.Popup.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,"dropdown-dark-fixture.png"));}popupList.SelectedIndex=39;Call(popupList,"OnKeyDown",new KeyEventArgs(Keys.Enter));Check(combo.SelectedIndex==39&&combo.Popup==null,"popup keyboard commit");Call(combo,"OnKeyDown",new KeyEventArgs(Keys.Up));Check(combo.SelectedIndex==38,"choice keyboard navigation");form.Close();
   }
   return "PASS custom scrollbars: 1,200 grid rows, 372 tree nodes, 5,000 log lines; both axes, wheel accumulation, thumb drag, track paging, keyboard Home/PageDown, live-cell selection, log selection/viewport persistence, collapse/empty states, handle recreation, accessible role/value, dark popup overflow and keyboard choice commit (isolated fixtures)";
  }
 }
}
